{
  "name": "Pfeiffer TPG 261 真空计",
  "name_en": "Pfeiffer TPG 261 Vacuum Gauge",
  "manufacturer": "Pfeiffer",
  "description": "用于测量和读取真空系统中的压力值，适合实验腔体、真空管路或泵组的真空状态监测。",
  "description_en": "Used to measure and read pressure in vacuum systems, suitable for vacuum state monitoring of chambers, vacuum lines, or pumping setups.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到真空计的通信接口。",
      "description_en": "Connect to the vacuum gauge communication interface."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与真空计的通信连接。",
      "description_en": "Disconnect communication with the vacuum gauge."
    },
    {
      "action_name": "auto-rcv_vals",
      "description": "接收真空压力读数的原始字节数据。",
      "description_en": "Receive the raw byte data of the vacuum pressure reading."
    }
  ],
  "tag_hints": [
    "vacuum measurement",
    "vacuum gauge",
    "pressure sensing",
    "Pfeiffer TPG261",
    "chamber pressure monitoring"
  ]
}

